"""Ledger parsing, totals, filtering and shared formatting helpers."""

import re
from dataclasses import dataclass
from datetime import date
from decimal import Decimal
from typing import Dict, Iterable, List, Optional

_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$", re.ASCII)
_AMOUNT_RE = re.compile(r"^[+-]?\d+(\.\d{1,2})?$", re.ASCII)
_WS_SPLIT = re.compile(r"[ \t]+")
_CENT = Decimal("0.01")


class ParseError(ValueError):
    """A ledger line is malformed. ``line`` is the 1-based line number."""

    def __init__(self, line: int, reason: str):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Entry:
    date: date
    category: str
    amount: Decimal
    note: str = ""


def _parse_line(text: str, lineno: int) -> Entry:
    stripped = text.strip(" \t\r\v\f")
    parts = _WS_SPLIT.split(stripped, 3)
    if len(parts) < 3:
        raise ParseError(lineno, "expected DATE CATEGORY AMOUNT [NOTE]")
    date_s, category, amount_s = parts[0], parts[1], parts[2]
    note = parts[3].strip() if len(parts) > 3 else ""
    if not _DATE_RE.match(date_s):
        raise ParseError(lineno, "invalid date %r" % date_s)
    try:
        d = date(int(date_s[:4]), int(date_s[5:7]), int(date_s[8:10]))
    except ValueError:
        raise ParseError(lineno, "invalid date %r" % date_s) from None
    if not _AMOUNT_RE.match(amount_s):
        raise ParseError(lineno, "invalid amount %r" % amount_s)
    return Entry(d, category.lower(), Decimal(amount_s), note)


def parse(text: str) -> List[Entry]:
    """Parse ledger text into entries, in file order."""
    entries = []
    for lineno, line in enumerate(text.splitlines(), 1):
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        entries.append(_parse_line(line, lineno))
    return entries


def balance(entries: Iterable[Entry]) -> Decimal:
    total = Decimal(0)
    for e in entries:
        total += e.amount
    return total


def by_category(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    out = {}  # type: Dict[str, Decimal]
    for e in entries:
        out[e.category] = out.get(e.category, Decimal(0)) + e.amount
    return out


def by_month(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    out = {}  # type: Dict[str, Decimal]
    for e in entries:
        key = "%04d-%02d" % (e.date.year, e.date.month)
        out[key] = out.get(key, Decimal(0)) + e.amount
    return out


def filter_entries(
    entries: Iterable[Entry],
    category: Optional[str] = None,
    since: Optional[date] = None,
    until: Optional[date] = None,
) -> List[Entry]:
    cat = category.lower() if category is not None else None
    out = []
    for e in entries:
        if cat is not None and e.category != cat:
            continue
        if since is not None and e.date < since:
            continue
        if until is not None and e.date > until:
            continue
        out.append(e)
    return out


def format_amount(amount: Decimal) -> str:
    q = Decimal(amount).quantize(_CENT)
    if q == 0:
        q = abs(q)
    return format(q, "f")


def format_entry(entry: Entry) -> str:
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    note = entry.note.strip()
    if note:
        line += " " + note
    return line
"""Command-line interface for pennywise."""

import argparse
import csv
import io
import json
import sys
from datetime import date

from .core import (
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    parse,
)


class _LedgerReadError(Exception):
    """File cannot be read or decoded (exit 2)."""


def _date_arg(value):
    try:
        if len(value) != 10 or value[4] != "-" or value[7] != "-":
            raise ValueError(value)
        if not (value[:4] + value[5:7] + value[8:]).isascii():
            raise ValueError(value)
        return date(int(value[:4]), int(value[5:7]), int(value[8:]))
    except ValueError:
        raise argparse.ArgumentTypeError(
            "invalid date %r (expected YYYY-MM-DD)" % value
        ) from None


def _build_parser():
    p = argparse.ArgumentParser(
        prog="pennywise", description="Report where the money went from a plain-text ledger."
    )
    sub = p.add_subparsers(dest="command", metavar="COMMAND")

    s = sub.add_parser("balance", help="print the total balance")
    s.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("summary", help="print totals per category or month")
    s.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    s.add_argument("--by", choices=["category", "month"], default="category")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("list", help="list entries, oldest first")
    s.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    s.add_argument("--category", metavar="C")
    s.add_argument("--since", metavar="DATE", type=_date_arg)
    s.add_argument("--until", metavar="DATE", type=_date_arg)
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("export", help="export entries")
    s.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    s.add_argument("--format", choices=["csv"], default="csv")

    s = sub.add_parser("add", help="append an entry to a ledger file")
    s.add_argument("file", metavar="FILE")
    s.add_argument("date", metavar="DATE")
    s.add_argument("category", metavar="CATEGORY")
    s.add_argument("amount", metavar="AMOUNT")
    s.add_argument("note", metavar="NOTE", nargs="?", default="")
    return p


def _read_ledger(path):
    if path == "-":
        try:
            text = sys.stdin.read()
        except (OSError, UnicodeError) as e:
            raise _LedgerReadError("cannot read standard input: %s" % e)
    else:
        try:
            with open(path, "rb") as f:
                data = f.read()
            text = data.decode("utf-8")
        except OSError as e:
            raise _LedgerReadError("%s: %s" % (path, e.strerror or e))
        except UnicodeError:
            raise _LedgerReadError("%s: not valid UTF-8" % path)
    if text.startswith("﻿"):
        text = text[1:]
    return text


def _load(path):
    text = _read_ledger(path)
    try:
        return parse(text)
    except ParseError as e:
        name = "<stdin>" if path == "-" else path
        raise _LedgerParseError("%s: %s" % (name, e))


class _LedgerParseError(Exception):
    """Ledger has a mistake (exit 1)."""


def _json(obj):
    return json.dumps(obj, ensure_ascii=False) + "\n"


def _cmd_balance(args):
    total = format_amount(balance(_load(args.file)))
    return _json({"balance": total}) if args.json else total + "\n"


def _cmd_summary(args):
    entries = _load(args.file)
    totals = by_month(entries) if args.by == "month" else by_category(entries)
    rows = [(name, format_amount(totals[name])) for name in sorted(totals)]
    if args.json:
        return _json(dict(rows))
    return "".join("%s  %s\n" % row for row in rows)


def _sorted_filtered(args):
    entries = filter_entries(
        _load(args.file),
        category=getattr(args, "category", None),
        since=getattr(args, "since", None),
        until=getattr(args, "until", None),
    )
    return sorted(entries, key=lambda e: e.date)


def _cmd_list(args):
    entries = _sorted_filtered(args)
    if args.json:
        return _json(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": format_amount(e.amount),
                    "note": e.note,
                }
                for e in entries
            ]
        )
    return "".join(format_entry(e) + "\n" for e in entries)


def _cmd_export(args):
    entries = _sorted_filtered(args)
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\n")
    w.writerow(["date", "category", "amount", "note"])
    for e in entries:
        w.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    return buf.getvalue()


def _build_entry_line(args):
    for value in (args.date, args.category, args.amount):
        if not value or any(c.isspace() for c in value):
            raise ParseError(1, "fields must be non-empty and contain no whitespace: %r" % value)
    note = args.note
    if len(note.splitlines()) > 1 or "\r" in note or "\n" in note:
        raise ParseError(1, "note must not contain line breaks")
    line = "%s %s %s" % (args.date, args.category, args.amount)
    if note.strip():
        line += " " + note
    return line


def _cmd_add(args):
    try:
        entries = parse(_build_entry_line(args))
    except ParseError as e:
        raise _LedgerParseError(str(e))
    entry = entries[0]
    line = format_entry(entry)
    try:
        prefix = ""
        try:
            with open(args.file, "rb") as f:
                f.seek(0, io.SEEK_END)
                if f.tell() > 0:
                    f.seek(-1, io.SEEK_END)
                    if f.read(1) not in (b"\n", b"\r"):
                        prefix = "\n"
        except FileNotFoundError:
            pass
        with open(args.file, "ab") as f:
            f.write((prefix + line + "\n").encode("utf-8"))
    except OSError as e:
        raise _LedgerReadError("%s: %s" % (args.file, e.strerror or e))
    return line + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
    "add": _cmd_add,
}


def main(argv=None):
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as e:
        code = e.code
        return code if isinstance(code, int) else (0 if code is None else 2)
    if not args.command:
        parser.print_usage(sys.stderr)
        sys.stderr.write("pennywise: error: a command is required\n")
        return 2
    try:
        out = _COMMANDS[args.command](args)
    except _LedgerParseError as e:
        sys.stderr.write("pennywise: %s\n" % e)
        return 1
    except _LedgerReadError as e:
        sys.stderr.write("pennywise: %s\n" % e)
        return 2
    sys.stdout.write(out)
    return 0


if __name__ == "__main__":
    sys.exit(main())
